// I2C写EEPROM(寄存器方式)
uint8_t data = 0x55;
HAL_I2C_Mem_Write(&hi2c1, 0xA0, 0x00, I2C_MEMADD_SIZE_8BIT, 
                   &data, 1, 100);

// I2C读EEPROM
uint8_t val;
HAL_I2C_Mem_Read(&hi2c1, 0xA0, 0x00, I2C_MEMADD_SIZE_8BIT, 
                 &val, 1, 100);

// 注意：EEPROM写后有5ms写周期
// 连续写需等待
HAL_Delay(5);

// 主机方式(无寄存器地址)
uint8_t buf[] = {0x01, 0x02};
HAL_I2C_Master_Transmit(&hi2c1, 0x40, buf, 2, 100);

// EEPROM读写封装
#define EEPROM_ADDR 0xA0  // 0x50<<1

// 写1字节
void eepromWriteByte(uint8_t addr, uint8_t data) {
    HAL_I2C_Mem_Write(&hi2c1, EEPROM_ADDR, addr, 
                      I2C_MEMADD_SIZE_8BIT, &data, 1, 100);
    HAL_Delay(5);  // 写周期
}

// 读1字节
uint8_t eepromReadByte(uint8_t addr) {
    uint8_t data;
    HAL_I2C_Mem_Read(&hi2c1, EEPROM_ADDR, addr, 
                     I2C_MEMADD_SIZE_8BIT, &data, 1, 100);
    return data;
}

// 使用
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_I2C1_Init();

    eepromWriteByte(0x00, 0xAA);
    uint8_t val = eepromReadByte(0x00);
    printf("读出:0x%02x\r\n", val);
}

// SPI读写Flash(W25Q64)
#define CS_LOW()  HAL_GPIO_WritePin(GPIOA, GPIO_PIN_4, GPIO_PIN_RESET)
#define CS_HIGH() HAL_GPIO_WritePin(GPIOA, GPIO_PIN_4, GPIO_PIN_SET)

// SPI发送接收1字节
uint8_t spiReadWrite(uint8_t txData) {
    uint8_t rxData;
    HAL_SPI_TransmitReceive(&hspi1, &txData, &rxData, 1, 100);
    return rxData;
}

// Flash读取ID
uint16_t flashReadID(void) {
    uint16_t id;
    CS_LOW();
    spiReadWrite(0x9F);  // 读ID命令
    id = spiReadWrite(0xFF) << 8;  // 厂商ID
    id |= spiReadWrite(0xFF);       // 类型ID
    CS_HIGH();
    return id;
}

// W25Q64读写
// 读数据
void flashRead(uint32_t addr, uint8_t* buf, uint16_t len) {
    CS_LOW();
    spiReadWrite(0x03);  // 读命令
    spiReadWrite((addr>>16)&0xFF);  // 地址24位
    spiReadWrite((addr>>8)&0xFF);
    spiReadWrite(addr&0xFF);
    for (int i = 0; i < len; i++) {
        buf[i] = spiReadWrite(0xFF);
    }
    CS_HIGH();
}

// 等待写完成
void flashWaitBusy(void) {
    uint8_t status;
    do {
        CS_LOW();
        spiReadWrite(0x05);  // 读状态
        status = spiReadWrite(0xFF);
        CS_HIGH();
    } while (status & 0x01);  // BUSY位
}

// 扇区擦除
void flashEraseSector(uint32_t addr) {
    CS_LOW();
    spiReadWrite(0x06);  // 写使能
    CS_HIGH();
    CS_LOW();
    spiReadWrite(0x20);  // 扇区擦除
    spiReadWrite((addr>>16)&0xFF);
    spiReadWrite((addr>>8)&0xFF);
    spiReadWrite(addr&0xFF);
    CS_HIGH();
    flashWaitBusy();
}

// 综合示例：EEPROM参数存储
struct Config {
    uint8_t brightness;
    uint8_t volume;
    uint16_t timeout;
};

void saveConfig(struct Config* cfg) {
    eepromWriteByte(0x00, cfg->brightness);
    eepromWriteByte(0x01, cfg->volume);
    eepromWriteByte(0x02, cfg->timeout & 0xFF);
    eepromWriteByte(0x03, (cfg->timeout >> 8) & 0xFF);
}

void loadConfig(struct Config* cfg) {
    cfg->brightness = eepromReadByte(0x00);
    cfg->volume = eepromReadByte(0x01);
    cfg->timeout = eepromReadByte(0x02) | (eepromReadByte(0x03) << 8);
}
